    local n = stat[1]:lower()
    local compact = n:gsub("%s+", ""):gsub("[^%w]", "")
    local income = stat[3]
    local rarity = stat[2]
    local cost = stat[4]
    -- Store multiple natural phrasings so questions do not need to match a template.
    for _, q in ipairs({
        n .. " income", "income of " .. n, "how much does " .. n .. " make",
        "how much does " .. n .. " generate", "how much money does " .. n .. " make",
