    }) do
        registerRiddleFact(q, income)
    end
    for _, q in ipairs({n .. " rarity", "rarity of " .. n, "what rarity is " .. n,
        "what is the rarity for " .. n, "which rarity is " .. n}) do
        registerRiddleFact(q, rarity)
    end
    if cost ~= "not listed" then
        for _, q in ipairs({n .. " cost", "cost of " .. n, "price of " .. n,
            "how much does " .. n .. " cost", "how much is " .. n,
            "buy price of " .. n, n .. " price"}) do
            registerRiddleFact(q, cost)
        end
    end
end

