-- Build a large synonym/word-order bank from known facts, not fabricated answers.
-- This creates thousands of additional searchable question variants at startup.
local VexoraQuestionOpeners = {
    "", "hey ", "quick question ", "question ", "do you know ", "can you tell me ",
    "please tell me ", "i need to know ", "answer this ", "trivia ", "random trivia ",
    "can someone tell me ", "what is the answer to ", "give me the answer to ",
    "i have a question ", "help me with this ", "riddle question ", "for trivia ",
}
local VexoraQuestionClosers = {
    "", "?", " please", " right now", " answer", " trivia", " quick", " for the riddle",
    " in the game", " in general", " do you know", " can you answer", " tell me",
}
local VexoraQuestionConnectors = {
    "", "what is ", "what's ", "whats ", "tell me ", "which is ", "name ", "identify ",
}
local VexoraVariantCount = 0
for _, fact in ipairs(VexoraCurrentFacts) do
    local base, answer = fact[1], fact[2]
    for _, opener in ipairs(VexoraQuestionOpeners) do
        for _, closer in ipairs(VexoraQuestionClosers) do
            local question = (opener .. base .. closer):lower():gsub("[%p%c]", " "):gsub("%s+", " "):match("^%s*(.-)%s*$")
            if question and #question >= 4 and #question <= 110 and RiddleDatabase[question] == nil then
                RiddleDatabase[question] = answer
                VexoraVariantCount += 1
            end
        end
    end
end
-- Additional variants are deliberately generated from the same verified base facts.
for _, fact in ipairs(VexoraCurrentFacts) do
    local base, answer = fact[1], fact[2]
    for _, connector in ipairs(VexoraQuestionConnectors) do
        for _, suffix in ipairs({"", " please", " thanks", " for me", " today", " right now"}) do
            local question = (connector .. base .. suffix):lower():gsub("[%p%c]", " "):gsub("%s+", " "):match("^%s*(.-)%s*$")
            if question and #question >= 4 and #question <= 110 and RiddleDatabase[question] == nil then
                RiddleDatabase[question] = answer
                VexoraVariantCount += 1
            end
        end
    end
end

